//#region src/components/forms/rating/rating.js
function formRating() {
	const ratings = document.querySelectorAll("[data-fls-rating]");
	if (ratings) ratings.forEach((rating) => {
		const ratingValue = +rating.dataset.flsRatingValue;
		formRatingInit(rating, +rating.dataset.flsRatingSize ? +rating.dataset.flsRatingSize : 5);
		ratingValue && formRatingSet(rating, ratingValue);
		document.addEventListener("click", formRatingAction);
	});
	function formRatingAction(e) {
		const targetElement = e.target;
		if (targetElement.closest(".rating__input")) {
			const currentElement = targetElement.closest(".rating__input");
			const ratingValue = +currentElement.value;
			const rating = currentElement.closest(".rating");
			rating.dataset.flsRating === "set" && formRatingGet(rating, ratingValue);
		}
	}
	function formRatingInit(rating, ratingSize) {
		let ratingItems = `<div class="rating__items">`;
		for (let index = 0; index < ratingSize; index++) ratingItems += `
      <label class="rating__item">
        <input class="rating__input" type="radio" name="rating" value="${index + 1}">
      </label>`;
		ratingItems += `</div>`;
		const valueEl = rating.querySelector(".rating__value");
		if (valueEl) valueEl.insertAdjacentHTML("afterend", ratingItems);
		else rating.insertAdjacentHTML("afterbegin", ratingItems);
	}
	function formRatingGet(rating, ratingValue) {
		formRatingSet(rating, ratingValue);
	}
	function formRatingSet(rating, value) {
		const ratingItems = rating.querySelectorAll(".rating__item");
		const resultFullItems = parseInt(value);
		const resultPartItem = value - resultFullItems;
		rating.hasAttribute("data-rating-title") && (rating.title = value);
		ratingItems.forEach((ratingItem, index) => {
			ratingItem.classList.remove("rating__item--active");
			ratingItem.querySelector("span") && ratingItems[index].querySelector("span").remove();
			if (index <= resultFullItems - 1) ratingItem.classList.add("rating__item--active");
			if (index === resultFullItems && resultPartItem) ratingItem.insertAdjacentHTML("beforeend", `<span style="width:${resultPartItem * 100}%"></span>`);
		});
	}
}
document.querySelector("[data-fls-rating]") && window.addEventListener("load", formRating);
//#endregion
//#region src/components/custom/location/location.js
window.addEventListener("load", () => {
	const mapEl = document.getElementById("map");
	if (!mapEl) return;
	const items = Array.from(document.querySelectorAll(".branches__item"));
	const card = document.querySelector(".map__card");
	const getCoords = (el) => ({
		lat: parseFloat(el.dataset.lat),
		lng: parseFloat(el.dataset.lng)
	});
	const updateCard = (el) => {
		if (!card) return;
		const title = card.querySelector(".map_title");
		const address = card.querySelector(".map__address");
		const phone = card.querySelector(".map__phone");
		const ratingValue = card.querySelector(".rating_value");
		const ratingCount = card.querySelector(".rating_count");
		const ratingWrapper = card.querySelector("[data-fls-rating]");
		const button = card.querySelector("[data-fls-button]");
		if (title) title.textContent = el.dataset.title;
		if (address) address.textContent = el.dataset.address;
		if (phone) phone.textContent = el.dataset.phone;
		if (ratingValue) ratingValue.textContent = el.dataset.rating;
		if (ratingCount) ratingCount.textContent = `(${el.dataset.reviews})`;
		if (ratingWrapper) ratingWrapper.setAttribute("data-fls-rating-value", el.dataset.rating);
		if (button) button.setAttribute("href", el.dataset.route);
	};
	let center;
	let defaultItem = null;
	if (items.length) {
		defaultItem = items.find((el) => el.dataset.default === "true") || items[items.length - 1];
		center = getCoords(defaultItem);
	} else center = {
		lat: parseFloat(mapEl.dataset.lat),
		lng: parseFloat(mapEl.dataset.lng)
	};
	const map = new google.maps.Map(mapEl, {
		zoom: 16,
		center
	});
	if (!items.length) {
		new google.maps.Marker({
			position: center,
			map
		});
		return;
	}
	items.forEach((el) => {
		const coords = getCoords(el);
		new google.maps.Marker({
			position: coords,
			map
		});
		el.addEventListener("click", () => {
			map.panTo(coords);
			map.setZoom(16);
			updateCard(el);
		});
	});
	if (defaultItem) updateCard(defaultItem);
});
//#endregion
